"""Rebuild the adapted template from recovered, localized CSS and explicit FMI bindings."""
from pathlib import Path
import re
root=Path(__file__).resolve().parents[1]
base='/assets/royal-heritage-wedding/'
css=(root/'public/assets/royal-heritage-wedding/fonts.css').read_text(encoding='utf-8')+(root/'public/assets/royal-heritage-wedding/recovered.css').read_text(encoding='utf-8')
def scope(s,hash):
 return re.sub(r'class="([^"]*)"',lambda m:'class="'+m[1]+' svelte-'+hash+'"',s)
def border():
 return '<div class="page_border" aria-hidden="true">'+''.join('<span class="border_line border_'+x+'"></span>' for x in ['top','right','bottom','left'])+''.join('<span class="border_gem '+x+'"></span>' for x in ['tl','tr','bl','br'])+'</div>'
def divider():return '<div class="ornate_divider"><span class="div_line"></span><span class="div_diamond"></span><span class="div_line"></span></div>'
def lamps():
 return ''.join('<div class="chirag chirag_'+side+'"><span class="chirag_floor_glow"></span><img class="chirag_img" src="'+base+'451507af5120d4a1.webp" alt=""><span class="chirag_glow"></span>'+''.join('<span class="chirag_spark chirag_spark_'+str(i)+'"></span>' for i in range(1,4))+'</div>' for side in ['left','right'])
def section(id,hash,content):return scope('<section class="component-content mobile" data-section="'+id+'">'+content+'</section>',hash)
hero=section('hero','xk606g','<div class="hero_screen"><div class="hero_backdrop"></div><div class="hero_vignette"></div>'+border()+lamps()+'<div class="hero_content page_enter_bloom"><h4 class="welcome_text shimmer_text anim_fade_in_up" data-editor-text="text-7001">Welcome to the Wedding of</h4><div class="couple_block shimmer_text anim_fade_in_up" style="font-family:Amiri,Georgia,serif;font-style:italic;font-weight:700;font-size:3.5rem"><span data-field="groom">Rohan</span><br><span>and</span><br><span data-field="bride">Ananya</span></div>'+divider()+'<div class="event_date shimmer_text anim_fade_in_up" data-field="date">2026-12-20</div></div></div>')
count=section('countdown','1vsz8x1','<div class="countdown_page"><div class="countdown_backdrop"><img class="backdrop_img" src="'+base+'84e3f51895a068b5.webp" alt=""></div><div class="countdown_vignette"></div>'+border()+'<div class="countdown_content"><div class="ganesh_emblem"><img class="ganesh_img" src="'+base+'04ba7c1e19dc3fd7.webp" alt="Ganesha"></div><h4 class="section_heading" data-editor-text="text-7002">Countdown to Our</h4><h2 class="main_title" data-editor-text="text-7003">Big Day</h2>'+divider()+'<div class="countdown_grid">'+''.join('<div class="cd_box" style="--cd-i:'+str(i)+'"><img class="cd_box_img" src="'+base+'3ed997b683cb34ea.webp" alt=""><strong class="cd_number" id="count-'+str(i)+'">00</strong><span class="cd_label">'+label+'</span></div>' for i,label in enumerate(['DAYS','HRS','MINS','SECS']))+'</div></div></div>')
about=section('welcome','qnpquh','<div class="about_screen"><div class="about_backdrop"></div><div class="about_vignette"></div>'+border()+'<div class="about_inner page_enter_rise"><h4 class="section_heading anim_fade_in_up" data-editor-text="text-7004">About Us</h4><p class="fmi-welcome" data-field="welcome"></p>'+''.join('<article class="person_frame anim_flip_in"><div class="frame_inner"><span class="person_role">The '+role+'</span><h3 class="person_name" data-field="'+key+'"></h3><div class="mini_divider"></div><p class="person_about" data-field="'+key+'Details"></p></div></article>' for role,key in [('Groom','groom'),('Bride','bride')])+'</div></div>')
events=section('timeline','3dh9ld','<div class="event_screen"><div class="event_backdrop"></div><div class="event_vignette"></div>'+border()+'<div class="event_inner page_enter_slide"><h4 class="section_heading anim_fade_in_up" data-editor-text="text-7005">Events</h4><div class="events_grid"><div data-events="preEvents"></div><div data-events="timeline"></div></div><div class="fmi-venue" data-section="venue"><h3 data-field="venue"></h3><p data-field="address"></p><p><span data-field="date"></span> · <span data-field="time"></span></p><a id="directions" href="https://maps.google.com/">Get directions</a><button type="button" id="calendar">Save the date</button></div></div></div>')
gallery=section('gallery','iu7qbz','<div class="gallery_screen"><div class="gallery_backdrop"></div><div class="gallery_vignette"></div>'+border()+'<div class="gallery_inner page_enter_blur"><h4 class="section_heading anim_fade_in_up" data-editor-text="text-7006">Gallery</h4>'+divider()+'<div class="deck_wrap"><div class="deck_shadow"></div><div class="deck">'+''.join('<figure class="card"><div class="card_inner"><img class="card_img" data-photo="'+str(i)+'" src="/assets/e4e5ca7a8c0c7b74.jpg" alt="Wedding memory '+str(i+1)+'" draggable="false"><div class="card_overlay"></div></div></figure>' for i in range(4))+'</div></div><div class="fmi-gallery-controls"><button id="prev" aria-label="Previous photo">←</button><span id="photo-status" data-no-edit aria-live="polite"></span><button id="next" aria-label="Next photo">→</button></div></div></div>')
thanks=section('rsvp','zf75h0','<div class="thanks_screen"><img class="thanks_backdrop_img" src="'+base+'364e5ed899368f4d.webp" alt=""><div class="thanks_vignette"></div>'+border()+lamps()+'<div class="fmi-thanks"><h2 data-editor-text="text-7007">Thank You!</h2><div class="fmi-couple"><span data-field="groom"></span><span> & </span><span data-field="bride"></span></div><p data-editor-text="text-7008">Your presence and blessings would mean the world to us as we begin this beautiful journey together.</p><button id="rsvp-open">Send your RSVP</button><button id="share">Share this invitation</button><p id="share-status" role="status"></p><small>With love · FindMyInvite</small></div></div>')
extra=r"""
*{box-sizing:border-box}html,body{margin:0;--hundred_vh:100svh;background:#2a1408;color:#f2dbb0}button,a{touch-action:manipulation}button{cursor:pointer}button:focus-visible,a:focus-visible{outline:2px solid #fff3d1;outline-offset:5px}button,.fmi-venue a{font-family:Cinzel,Georgia,serif;border:1px solid #d4a574;color:#f4d585;background:#301710;padding:12px 20px;border-radius:3px;letter-spacing:1px;text-decoration:none}.fmi-welcome{max-width:360px;font:italic 19px/1.6 'Cormorant Garamond',serif;margin:0 0 30px}.person_frame{margin-bottom:24px}.fmi-venue{padding:30px 15px;max-width:440px;margin:auto;text-align:center}.fmi-venue h3{font:42px Italianno,cursive}.fmi-venue p{font:18px/1.6 'Cormorant Garamond',serif}.fmi-venue button,.fmi-venue a{display:inline-block;margin:5px}.events_grid{display:block!important}.fmi-event-card{background:url(/assets/royal-heritage-wedding/721e82c2a9dcaf45.webp) center/100% 100% no-repeat;min-height:440px;display:flex;flex-direction:column;justify-content:center;align-items:center;margin:20px auto!important;max-width:350px;padding:90px 55px!important}.fmi-event-card h3{font:42px Italianno,cursive!important}.fmi-event-card p{font:18px/1.5 'Cormorant Garamond',serif}.fmi-gallery-controls{display:flex;justify-content:center;align-items:center;gap:18px;margin-top:20px}.deck .card{transition:transform .55s ease,opacity .55s ease}.fmi-thanks{position:relative;z-index:3;margin:auto;max-width:400px;padding:150px 24px;text-align:center}.fmi-thanks h2{font:68px Italianno,cursive;color:#f4d585}.fmi-couple{font:40px/1.2 Italianno,cursive}.fmi-thanks p{font:italic 20px/1.6 'Cormorant Garamond',serif}.fmi-thanks button{margin:6px}.fmi-thanks small{display:block;margin-top:30px}dialog{max-width:min(440px,92vw);max-height:85svh;overflow:auto;color:#f2dbb0;background:#2a1408;border:1px solid #d4a574;border-radius:12px;padding:25px}dialog::backdrop{background:#000b}dialog label{display:grid;gap:7px;margin:14px 0}dialog input,dialog select,dialog textarea{width:100%;padding:12px;font:16px Georgia;background:#fff9ec;color:#301710;border:0;border-radius:4px}#rsvp-close{float:right}#opening{position:fixed;inset:0;z-index:99;display:grid;place-items:center;text-align:center;background:#1e0b06;overflow:hidden}#opening:before,#opening:after{content:'';position:absolute;top:0;bottom:0;width:50%;background:linear-gradient(90deg,#1e0b06bb,#1e0b0644),url(/assets/royal-heritage-wedding/364e5ed899368f4d.webp) center/cover;border:1px solid #b88b4e;transition:transform 1.4s cubic-bezier(.65,0,.35,1)}#opening:before{left:0}#opening:after{right:0}#opening.open:before{transform:translateX(-100%)}#opening.open:after{transform:translateX(100%)}.opening-copy{z-index:1;position:relative;color:#f4d585;transition:opacity .5s;padding:30px}.opening-copy h1{font:54px/1.1 Italianno,cursive}.opening-copy p{font:12px Cinzel,serif;letter-spacing:3px}#opening.open .opening-copy{opacity:0;pointer-events:none}body.closed{overflow:hidden}@media(min-width:800px){.hero_content{max-width:400px}.about_inner{max-width:520px}.fmi-event-card{max-width:420px;min-height:520px}}@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation:none!important;transition:none!important}.anim_fade_in,.anim_fade_in_up,.anim_flip_in,.frame_inner,.ganesh_emblem,.cd_box,.section_heading,.main_title,.ornate_divider{opacity:1!important;transform:none!important}}
"""
script=r"""
(()=>{const q=s=>document.querySelector(s),all=s=>[...document.querySelectorAll(s)];let opened=false;const reveal=()=>{if(opened)return;opened=true;q('#opening').classList.add('open');document.body.classList.remove('closed');setTimeout(()=>q('#opening').hidden=true,matchMedia('(prefers-reduced-motion: reduce)').matches?0:1450)};q('#open').onclick=reveal;addEventListener('message',e=>{if(e.source===parent&&e.data?.type==='editing'&&e.data.enabled)reveal()});const observer=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in_view','show');all.call(null,'.page_enter_bloom,.page_enter_rise,.page_enter_slide,.page_enter_blur').filter(x=>e.target.contains(x)).forEach(x=>x.classList.add('in_view'));}}),{threshold:.08});all('section.component-content').forEach(x=>observer.observe(x));let slide=0;function show(){const cards=all('.deck .card').filter(c=>!c.querySelector('img').hidden);cards.forEach((c,i)=>{const n=(i-slide+cards.length)%cards.length;c.style.zIndex=String(cards.length-n);c.style.transform='translate(calc(-50% + '+(n%2? -6:6)*n+'px),calc(-50% + '+n*7+'px)) rotate('+(n===0?0:n%2?-5:4)+'deg) scale('+(1-n*.025)+')';c.style.opacity='1';});q('#photo-status').textContent=cards.length?(slide+1)+' / '+cards.length:'Add your memories';}function next(n){const count=all('.deck .card').filter(c=>!c.querySelector('img').hidden).length;slide=count?(slide+n+count)%count:0;show()}q('#prev').onclick=()=>next(-1);q('#next').onclick=()=>next(1);let startX=0;q('.deck').addEventListener('pointerdown',e=>startX=e.clientX);q('.deck').addEventListener('pointerup',e=>{if(Math.abs(e.clientX-startX)>35)next(e.clientX<startX?1:-1)});setInterval(()=>{if(!matchMedia('(prefers-reduced-motion: reduce)').matches)next(1)},5000);const tick=()=>{const d=window.fmiData||{},diff=Math.max(0,Date.parse(d.date+'T'+(d.time||'00:00')+':00+05:30')-Date.now());[Math.floor(diff/86400000),Math.floor(diff/3600000)%24,Math.floor(diff/60000)%60,Math.floor(diff/1000)%60].forEach((n,i)=>q('#count-'+i).textContent=String(Number.isFinite(n)?n:0).padStart(2,'0'))};setInterval(tick,1000);document.addEventListener('fmi:updated',()=>{tick();show();const d=window.fmiData;q('#directions').href='https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(d.venue+' '+d.address)});q('#rsvp-open').onclick=()=>q('#rsvp-dialog').showModal();q('#rsvp-close').onclick=()=>q('#rsvp-dialog').close();q('#calendar').onclick=()=>{const d=window.fmiData||{},start=new Date(d.date+'T'+d.time+':00+05:30');if(!Number.isFinite(+start))return;const stamp=d=>d.toISOString().replace(/[-:]/g,'').split('.')[0]+'Z',escape=s=>String(s||'').replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/[,;]/g,'\\$&');const text=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//FindMyInvite//EN','BEGIN:VEVENT','UID:'+escape(d.id)+'@findmyinvite.com','DTSTAMP:'+stamp(new Date()),'DTSTART:'+stamp(start),'DTEND:'+stamp(new Date(+start+10800000)),'SUMMARY:'+escape(d.groom+' & '+d.bride),'LOCATION:'+escape(d.venue+' '+d.address),'END:VEVENT','END:VCALENDAR'].join(String.fromCharCode(13,10));const url=URL.createObjectURL(new Blob([text],{type:'text/calendar'})),a=document.createElement('a');a.href=url;a.download='wedding.ics';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};q('#share').onclick=()=>{q('#share-status').textContent='Copy the invitation address from your browser and share it with your guests.'};show();})();
"""
opening='<div id="opening"><div class="opening-copy"><p>YOU ARE CORDIALLY INVITED</p><h1><span data-field="groom"></span> &amp; <span data-field="bride"></span></h1><p data-field="date"></p><button id="open">Open Invitation</button></div></div>'
form='<dialog id="rsvp-dialog"><button type="button" id="rsvp-close" aria-label="Close RSVP">×</button><h2>Celebrate with us</h2><form id="fmi-rsvp"><label>Your name<input name="name" required maxlength="120"></label><label>Email<input name="email" type="email" required maxlength="254"></label><label>Will you attend?<select name="attendance"><option value="yes">Joyfully attending</option><option value="no">Regretfully declining</option></select></label><label>Guests<input name="guests" type="number" min="1" max="100" value="1"></label><label>Your message<textarea name="message" maxlength="2000"></textarea></label><button type="submit">Send RSVP</button><p id="fmi-rsvp-status" role="status"></p></form></dialog>'
html='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Royal Heritage Wedding | FindMyInvite</title><style>'+css+extra+'</style></head><body class="closed">'+opening+hero+count+about+events+gallery+thanks+form+'<script>'+script+'</script></body></html>'
(root/'public/studio/templates/royal-heritage-wedding.html').write_text(html,encoding='utf-8')
print('Template bytes',len(html.encode()))
